subplot(2,1,1); title('Samples'); xlabel('Sample Index'); ylabel('Amplitude'); legend; grid on;
subplot(2,1,2); title('Samples Magnitude'); xlabel('Sample Index'); ylabel('Magnitude'); legend; grid on;
