figure;subplot(2,1,1); hold on;plot(TX_FRAME_FREQ, real(TX_FRAME_FFT), 'DisplayName', 'Re(FFT)');plot(TX_FRAME_FREQ, imag(TX_FRAME_FFT), 'DisplayName', 'Im(FFT)');
subplot(2,1,1); title('FFT TX\_FRAME'); xlabel('Normalized Frequency'); ylabel('Amplitude'); legend; grid on;
